-- Supplier branches (real locations) so a quote can default to the nearest one.
-- Researched 8 Nov 2026 from each supplier's own site where readable (confidence 'site'), else web search ('search').
-- Locations geocoded with OpenStreetMap Nominatim. Nothing here is a price.

alter table public.suppliers add column if not exists branch_finder_url text;
create table if not exists public.supplier_branches (
  id uuid primary key default gen_random_uuid(),
  supplier_id uuid not null references public.suppliers(id) on delete cascade,
  name text not null, street text, suburb text not null, state text not null check (state in ('NSW','VIC','QLD','WA','SA','TAS','ACT','NT')), postcode text, phone text,
  lat double precision, lng double precision, geo_precision text check (geo_precision in ('address','suburb')),
  source_url text, confidence text not null default 'search' check (confidence in ('site','search')), checked_on date not null default current_date,
  unique (supplier_id, name)
);
create index if not exists supplier_branches_state on public.supplier_branches (state);
alter table public.supplier_branches enable row level security;
drop policy if exists supplier_branches_read on public.supplier_branches;
create policy supplier_branches_read on public.supplier_branches for select to authenticated using (true);
-- Which branch an org buys from (for distance and the order email).
alter table public.org_suppliers add column if not exists branch_id uuid references public.supplier_branches(id) on delete set null;

