on conflict (slug) do update set branch_finder_url = coalesce(excluded.branch_finder_url, suppliers.branch_finder_url),
  website = coalesce(suppliers.website, excluded.website),
  states = case when cardinality(suppliers.states) = 0 then excluded.states else suppliers.states end;
update public.suppliers set name = 'LUTUM (formerly Boral Roofing)', notes = 'Boral sold its roofing business to Lutum in Sept 2021; it now trades as LUTUM.' where slug = 'boral-lutum';

